import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Module 11 · Multisig treasury","description":"","frontmatter":{},"headers":[],"relativePath":"modules/11-multisig-treasury.md","filePath":"modules/11-multisig-treasury.md","lastUpdated":1790431304000}'),n={name:"modules/11-multisig-treasury.md"};function o(r,e,h,l,d,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="module-11-·-multisig-treasury" tabindex="-1">Module 11 · Multisig treasury <a class="header-anchor" href="#module-11-·-multisig-treasury" aria-label="Permalink to &quot;Module 11 · Multisig treasury&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Contract</strong></td><td><code>TownTreasury.sol</code></td></tr><tr><td><strong>Stop</strong></td><td>Council</td></tr><tr><td><strong>Pattern</strong></td><td>M-of-N multisignature wallet</td></tr><tr><td><strong>Stamp</strong></td><td>Module 11 (awarded to whoever <strong>executes</strong>)</td></tr></tbody></table><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>A single key controls everything it owns, absolutely and irreversibly. One phishing email, one compromised laptop, one person who leaves badly, and the town&#39;s funds are gone with no appeal.</p><p>Organisations do not run bank accounts this way. They require two signatures on a cheque, four eyes on a payment, a board resolution above a threshold. Those controls exist because concentrating authority in one person is a known failure mode, not a hypothetical one.</p><h2 id="the-idea" tabindex="-1">The idea <a class="header-anchor" href="#the-idea" aria-label="Permalink to &quot;The idea&quot;">​</a></h2><p><strong>M of N.</strong> A shared account with several owners, where a payment happens only when at least M of them agree. No single key is sufficient, and losing one key is survivable.</p><p>Trustville&#39;s treasury adds one more idea worth dwelling on: the treasury governs <strong>itself</strong>. Adding an owner, removing one, or changing the threshold are ordinary proposals that the treasury executes on itself. There is no admin.</p><h2 id="key-terms" tabindex="-1">Key terms <a class="header-anchor" href="#key-terms" aria-label="Permalink to &quot;Key terms&quot;">​</a></h2><p><strong>Multisig.</strong> A contract requiring M signatures from N owners. In practice on Ethereum this is a contract that counts confirmations, not cryptographic multi-signature.</p><p><strong>Threshold.</strong> The M. Choosing it is a real trade-off: too low and it is barely a control, too high and one absent owner freezes the treasury. 2-of-3 and 3-of-5 are the common answers.</p><p><strong>Arbitrary call.</strong> The proposal carries <code>to</code>, <code>value</code> and <code>data</code>, so it can call any function on any contract, not merely send money. This is what makes a multisig a general administrator rather than a wallet.</p><p><strong>Self-governance.</strong> A contract whose only administrator is itself. Elegant, and one misconfiguration away from being permanently stuck.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Payment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> to;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    uint256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> value;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// native TRUST sent with the call</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    bytes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> data;      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// contract call, e.g. an ERC-20 transfer</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> memo;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    uint32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> confirmations;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    bool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> executed;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Function</th><th>Who</th><th>What</th></tr></thead><tbody><tr><td><code>propose(to, value, data, memo)</code></td><td>an owner</td><td>Creates it — and confirms it</td></tr><tr><td><code>confirm(id)</code></td><td>an owner</td><td>One confirmation each</td></tr><tr><td><code>revokeConfirmation(id)</code></td><td>an owner</td><td>Only before execution</td></tr><tr><td><code>execute(id)</code></td><td><strong>anyone</strong></td><td>Only at or above the threshold</td></tr><tr><td><code>addOwner</code> / <code>removeOwner</code> / <code>setThreshold</code></td><td><strong>the treasury itself</strong></td><td>Via a proposal</td></tr><tr><td><code>encodeTransfer(to, amount)</code></td><td>view helper</td><td>Builds ERC-20 call data</td></tr></tbody></table><p>Three sentences in that table carry most of the design.</p><p><strong>Proposing is confirming.</strong> <code>propose</code> calls <code>_confirm(id, msg.sender)</code> at the end. An owner who puts a payment forward has obviously agreed to it; making them send a second transaction would be ceremony.</p><p><strong>Anyone may execute.</strong> Not just an owner:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> execute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">external</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (p.confirmations </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> threshold) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">revert</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> NotEnoughConfirmations</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(p.confirmations, threshold);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    p.executed </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;                  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// set BEFORE the call</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ok, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bytes</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> memory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> result) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> p.to.call{value</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> p.value}(p.data);</span></span></code></pre></div><p>The confirmations are the authority; the final transaction is just the button. This matters practically — an owner with no gas cannot block a payment everyone agreed to — and conceptually: authority lives in the recorded agreement, not in who happened to broadcast.</p><p><strong><code>executed</code> is set before the external call.</strong> Classic reentrancy guard by ordering. If the recipient calls back into <code>execute</code>, the flag is already true and it reverts. Getting this backwards is how the DAO was drained in 2016.</p><h2 id="the-detail-that-matters" tabindex="-1">The detail that matters <a class="header-anchor" href="#the-detail-that-matters" aria-label="Permalink to &quot;The detail that matters&quot;">​</a></h2><p><strong>The treasury is its own administrator:</strong></p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> addOwner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">address</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> owner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">external</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> onlyTreasury</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { … }</span></span></code></pre></div><p><code>onlyTreasury</code> means <code>msg.sender == address(this)</code>. The only way to reach it is a proposal whose <code>to</code> is the treasury and whose <code>data</code> encodes the call — so the existing owners must agree, at threshold, to change who the owners are.</p><p>This is the right design and it is unforgiving. Set the threshold above the owner count and nothing can ever be executed again, including the proposal that would lower it. Remove owners until fewer remain than the threshold and you have done the same thing. The contract guards the obvious cases with <code>BadThreshold</code>, but the general lesson stands: <strong>a contract that governs itself can lock itself out, and no one can help it.</strong></p><p>Before every owner or threshold change, ask: after this executes, can the remaining owners still reach the threshold?</p><p><strong>Revocation before execution.</strong> An owner can change their mind. Real multisigs need this — information arrives, a proposal turns out to be a mistake — and it must be impossible after execution, because by then the money is gone.</p><p><strong>The <code>memo</code> is for humans.</strong> The <code>data</code> field is bytes; nobody reads calldata in a hurry. The memo is what an owner sees before confirming, and it is unverified — a payment memoed &quot;office supplies&quot; can encode anything. The correct habit is to decode <code>data</code>, not to read <code>memo</code>. Teach yourself to distrust it now.</p><h2 id="walk-through-it" tabindex="-1">Walk through it <a class="header-anchor" href="#walk-through-it" aria-label="Permalink to &quot;Walk through it&quot;">​</a></h2><ol><li>The treasury is 2-of-3 with the instructor and two students as owners.</li><li><strong>Owner A:</strong> propose a TVD transfer. Use <code>encodeTransfer(recipient, amount)</code> to build the data, and give it an honest memo.</li><li>Check the proposal. One confirmation — A&#39;s own.</li><li><strong>Try to execute.</strong> <code>NotEnoughConfirmations(1, 2)</code>.</li><li><strong>Owner B:</strong> confirm. Now two.</li><li><strong>Anyone at all — a non-owner:</strong> execute. It works.</li><li>Try to execute again. <code>AlreadyExecuted</code>.</li></ol><p>Then the self-governance path:</p><ol start="8"><li>Propose a call to the treasury itself, encoding <code>addOwner(newAddress)</code>.</li><li>Confirm and execute. The owner set changed with no admin anywhere.</li><li>Before you do it, work out what the threshold will mean afterwards.</li></ol><h2 id="what-actually-happened-on-chain" tabindex="-1">What actually happened on chain <a class="header-anchor" href="#what-actually-happened-on-chain" aria-label="Permalink to &quot;What actually happened on chain&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PaymentProposed(id: 4, proposer: 0x…, to: 0x…, value: 0, memo: &quot;grant to the charity&quot;)</span></span>
<span class="line"><span>PaymentConfirmed(id: 4, owner: 0x…, confirmations: 1)</span></span>
<span class="line"><span>PaymentConfirmed(id: 4, owner: 0x…, confirmations: 2)</span></span>
<span class="line"><span>PaymentExecuted(id: 4, to: 0x…, result: 0x…01)</span></span>
<span class="line"><span>Stamped(tokenId: …, moduleId: 11, by: townTreasury)</span></span></code></pre></div><p>The <code>result</code> bytes are the return value of the inner call — <code>0x…01</code> here is an ERC-20 <code>transfer</code> returning true. When an execution fails, <code>CallFailed(reason)</code> carries the inner revert data, which is the only way to find out why a proposal that looked fine did not work.</p><h2 id="when-a-plain-database-is-better" tabindex="-1">When a plain database is better <a class="header-anchor" href="#when-a-plain-database-is-better" aria-label="Permalink to &quot;When a plain database is better&quot;">​</a></h2><p>A company bank account with dual authorisation does this, with a bank behind it, reversal for fraud, and a regulator. For most organisations that is simply better.</p><p>A multisig earns its place when <strong>the assets are on chain anyway</strong> — there is no bank for tokens — when the signers are in different countries or organisations with no shared institution, or when the control itself must be publicly auditable. Note that a large fraction of serious on-chain treasuries are multisigs rather than DAOs, because the DAO (module 12) is slower and its own security model is harder.</p><h2 id="what-this-does-not-fix" tabindex="-1">What this does not fix <a class="header-anchor" href="#what-this-does-not-fix" aria-label="Permalink to &quot;What this does not fix&quot;">​</a></h2><ul><li><strong>Compromise of M keys.</strong> If the same phishing campaign catches two of three owners, the threshold bought you nothing. Signers should differ in device, location and habits.</li><li><strong>Collusion.</strong> M owners who agree to steal are indistinguishable from M owners who agree to pay.</li><li><strong>Sending to the wrong address.</strong> Everyone confirms the same mistake.</li><li><strong>Malicious calldata.</strong> See the memo warning above.</li><li><strong>Owner absence.</strong> N−M owners unavailable and the treasury is frozen until they return.</li></ul><h2 id="security-checklist" tabindex="-1">Security checklist <a class="header-anchor" href="#security-checklist" aria-label="Permalink to &quot;Security checklist&quot;">​</a></h2><ul><li>[ ] Can a non-owner propose or confirm?</li><li>[ ] Can one owner confirm the same payment twice?</li><li>[ ] Is <code>executed</code> set before the external call?</li><li>[ ] Can the threshold be set above the owner count, now or after a removal?</li><li>[ ] Can an owner revoke after execution?</li><li>[ ] Does the reentrancy path through a hostile recipient reach anything?</li><li>[ ] Who, in the end, can add an owner — and is there any path that is not a proposal?</li></ul><h2 id="extend-it" tabindex="-1">Extend it <a class="header-anchor" href="#extend-it" aria-label="Permalink to &quot;Extend it&quot;">​</a></h2><ol><li>Add a timelock: executable only after a delay from reaching the threshold. Say what attack that stops and what it costs in an emergency. (Module 12 does exactly this.)</li><li>Add per-proposal expiry, so a stale confirmation set cannot be executed months later under different circumstances.</li><li>Add spending tiers — 1-of-3 below 10 TVD, 3-of-3 above 1000 — and notice you have just reinvented a corporate delegation of authority.</li><li>Decode <code>data</code> in the front end and show owners a human-readable summary before they confirm. This is the single highest-value improvement, and real multisig interfaces have spent years on it.</li></ol><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://docs.safe.global/" target="_blank" rel="noreferrer">Safe (formerly Gnosis Safe)</a> — the multisig most on-chain treasuries actually use. Compare its design with this one.</li><li><a href="https://docs.soliditylang.org/en/latest/security-considerations.html#reentrancy" target="_blank" rel="noreferrer">Reentrancy</a></li><li><a href="https://docs.soliditylang.org/en/latest/units-and-global-variables.html#abi-encoding-and-decoding-functions" target="_blank" rel="noreferrer"><code>abi.encodeWithSignature</code></a></li></ul><p><strong>Next:</strong> <a href="./12-dao-governance">Module 12 · DAO governance →</a></p>`,49)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
